CREATE PROCEDURE CLAIMS.EVALUATE_CLAIM
(
    IN P_CLAIM_ID BIGINT,
    OUT P_DECISION VARCHAR(30)
)
LANGUAGE SQL
BEGIN
    DECLARE V_RISK INTEGER DEFAULT 0;

    SELECT RISK_SCORE
      INTO V_RISK
      FROM CLAIM
     WHERE CLAIM_ID = P_CLAIM_ID;

    IF V_RISK >= 900 THEN
        SET P_DECISION = 'RISK_REVIEW';
    ELSE
        UPDATE CLAIM
           SET STATUS = 'APPROVED'
         WHERE CLAIM_ID = P_CLAIM_ID;
        SET P_DECISION = 'APPROVED';
    END IF;
END;
